use vstd::prelude::*;

verus! {

fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> (res: Vec<char>)
    ensures
        // Length is max(orig.len, width)
        res@.len() == if orig@.len() >= width as nat { orig@.len() } else { width as nat },

        // If no padding needed, result is exactly original
        orig@.len() >= width as nat ==> res@ == orig@,

        // If padding needed, original appears as a suffix and prefix is fillchar
        orig@.len() < width as nat ==> (
            res@.len() == width as nat
            && res@.subrange((width as nat) - orig@.len(), width as nat) == orig@
            && forall|i: nat|
                i < (width as nat) - orig@.len() ==> res@[i] == fillchar
        ),

        // Empty original: length equals width (follows from the first ensure, but stated explicitly)
        orig@.len() == 0 ==> res@.len() == width as nat,
{
    admit();
}

} // verus!